// Command gendocs generates Markdown reference pages for the full CLI command
// tree using cobra's GenMarkdownTree. The output lives under docs/commands/ and
// is consumed by the MkDocs site, so the command reference always matches the
// real --help output rather than being hand-maintained.
//
// Usage:
//
//	go run ./tools/gendocs            # writes to docs/commands
//	go run ./tools/gendocs -o <dir>   # custom output directory
//
// The generated files are checked in so the docs build does not require Go.
// Regenerate them whenever commands change (the docs CI also runs this).
package main

import (
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/spf13/cobra/doc"

	"github.com/jinjie/outsystems-cli/cmd"
)

func main() {
	outDir := flag.String("o", filepath.Join("docs", "commands"), "output directory for generated Markdown")
	flag.Parse()

	if err := run(*outDir); err != nil {
		fmt.Fprintln(os.Stderr, "gendocs:", err)
		os.Exit(1)
	}
}

func run(outDir string) error {
	root := cmd.RootCmd()
	// Disestablish the autogenerated "Auto generated by spf13/cobra" footer's
	// timestamp so regenerated files are stable (no spurious diffs).
	root.DisableAutoGenTag = true

	if err := os.MkdirAll(outDir, 0o755); err != nil {
		return fmt.Errorf("create output dir: %w", err)
	}

	// Clean previously generated command pages so removed commands don't linger.
	if err := cleanGenerated(outDir); err != nil {
		return err
	}

	// linkHandler keeps cross-links working as plain relative .md links, which
	// MkDocs resolves correctly.
	linkHandler := func(name string) string { return name }
	// filePrepender adds nothing; MkDocs derives the title from the first H1.
	filePrepender := func(string) string { return "" }

	if err := doc.GenMarkdownTreeCustom(root, outDir, filePrepender, linkHandler); err != nil {
		return fmt.Errorf("generate markdown: %w", err)
	}

	// Write an index page for the commands section.
	if err := writeIndex(outDir, root.Name()); err != nil {
		return err
	}

	fmt.Printf("gendocs: wrote command reference to %s\n", outDir)
	return nil
}

// cleanGenerated removes previously generated *.md files (everything except a
// hand-maintained index we rewrite anyway).
func cleanGenerated(dir string) error {
	entries, err := os.ReadDir(dir)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".md") {
			continue
		}
		if err := os.Remove(filepath.Join(dir, e.Name())); err != nil {
			return fmt.Errorf("clean %s: %w", e.Name(), err)
		}
	}
	return nil
}

// writeIndex creates an index.md linking to the top-level command page.
func writeIndex(dir, rootName string) error {
	content := fmt.Sprintf(`# Command reference

Auto-generated from the CLI command tree. Run `+"`%s --help`"+` for the same
information from your terminal.

Start at [`+"`%s`"+`](%s.md) for the root command and its subcommands.

!!! note
    These pages are generated by `+"`go run ./tools/gendocs`"+`. Do not edit
    them by hand; change the command definitions in `+"`cmd/`"+` instead.
`, rootName, rootName, rootName)

	return os.WriteFile(filepath.Join(dir, "index.md"), []byte(content), 0o644)
}
